// ── The agent's tools ────────────────────────────────────────────────────────
//
// There is no write tool in this file, and that is the point. The model can
// list, read and search; it cannot edit, commit, push or run anything. Phase 2
// adds a proposal tool that stages a change for review — still not a write —
// and the only thing that touches GitHub's write API will live behind the
// approval endpoint, not here.
//
// Every argument is validated before it becomes a request. A tool call is
// untrusted input: it is generated by a model from a prompt that may contain
// attacker-controlled repository text.

import type { SearchHit } from "@/lib/github/search";
import { formatHits } from "@/lib/github/search";
import { MAX_FILE_BYTES, isSafeRelativePath, rankPaths, type TreeFile } from "@/lib/github/tree";

export type ToolName = "list_files" | "read_file" | "search_code";

/** The names a tool call may use. Anything else is refused without a request. */
export const READ_ONLY_TOOLS: readonly ToolName[] = ["list_files", "read_file", "search_code"];

export interface AgentToolSchema {
  type: "function";
  function: {
    name: ToolName;
    description: string;
    parameters: Record<string, unknown>;
  };
}

export const AGENT_TOOL_SCHEMAS: AgentToolSchema[] = [
  {
    type: "function",
    function: {
      name: "list_files",
      description:
        "List source files in the repository. Use it first when you do not know the layout. Build output, dependencies and lockfiles are already excluded.",
      parameters: {
        type: "object",
        properties: {
          path: { type: "string", description: "Only list files under this directory. Omit for the whole repository." },
          depth: { type: "integer", description: "How many path segments to show. 1-3, default 2." },
        },
        additionalProperties: false,
      },
    },
  },
  {
    type: "function",
    function: {
      name: "read_file",
      description:
        "Read one file from the repository. Returns the text, or says why it cannot be read. Read the files you intend to talk about; do not guess at their contents.",
      parameters: {
        type: "object",
        properties: {
          path: { type: "string", description: "Repository-relative path, exactly as list_files returned it." },
        },
        required: ["path"],
        additionalProperties: false,
      },
    },
  },
  {
    type: "function",
    function: {
      name: "search_code",
      description:
        "Search the repository for a literal string. Returns file, line and the matching text. Prefer one distinctive term over a sentence.",
      parameters: {
        type: "object",
        properties: {
          query: { type: "string", description: "The text to find. Case-insensitive, literal, not a regex." },
        },
        required: ["query"],
        additionalProperties: false,
      },
    },
  },
];

/** What the tool needs from the request in order to do its job. */
export interface ToolContext {
  files: TreeFile[];
  readFile(path: string): Promise<{ text: string; truncated: boolean } | null>;
  search(query: string): Promise<SearchHit[]>;
}

export interface ParsedToolCall {
  id: string;
  name: string;
  /** Raw JSON string from the wire, parsed only after the name is allowed. */
  argumentJson: string;
}

export interface ToolResult {
  id: string;
  name: string;
  ok: boolean;
  /** One line for the timeline in the chat. */
  summary: string;
  /** What the model receives. Bounded by the tool. */
  content: string;
}

/** A readable label without exposing the raw argument object. */
function shortPath(path: string): string {
  return path.length > 60 ? `…${path.slice(-57)}` : path;
}

function parseArguments(argumentJson: string): Record<string, unknown> {
  if (!argumentJson.trim()) return {};
  try {
    const parsed = JSON.parse(argumentJson) as unknown;
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : {};
  } catch {
    return {};
  }
}

/** Six levels is already more than a repository list needs. */
function clampDepth(value: unknown): number {
  const depth = typeof value === "number" && Number.isFinite(value) ? Math.trunc(value) : 2;
  return Math.min(3, Math.max(1, depth));
}

/**
 * Runs one tool call.
 *
 * Never throws: a bad path or an unreadable file is a result the model can
 * react to, and a thrown exception would end the turn instead of teaching it
 * what went wrong.
 */
export async function runTool(call: ParsedToolCall, context: ToolContext): Promise<ToolResult> {
  const name = call.name as ToolName;
  if (!READ_ONLY_TOOLS.includes(name)) {
    return {
      id: call.id,
      name: call.name,
      ok: false,
      summary: `Refused ${call.name}`,
      content: `There is no tool named "${call.name}". Available tools: ${READ_ONLY_TOOLS.join(", ")}.`,
    };
  }

  const args = parseArguments(call.argumentJson);

  if (name === "list_files") {
    const wanted = typeof args.path === "string" ? args.path.trim() : "";
    if (wanted && !isSafeRelativePath(wanted)) {
      return { id: call.id, name, ok: false, summary: "Refused an unsafe path", content: "That path is not a relative path inside the repository." };
    }
    const depth = clampDepth(args.depth);
    const prefix = wanted ? `${wanted.replace(/\/+$/, "")}/` : "";
    const inScope = prefix ? context.files.filter((file) => file.path.startsWith(prefix)) : context.files;

    if (inScope.length === 0) {
      return {
        id: call.id,
        name,
        ok: true,
        summary: wanted ? `No files under ${shortPath(wanted)}` : "No files",
        content: wanted ? `No readable files under ${wanted}.` : "No readable files.",
      };
    }

    const shown = inScope.map((file) => {
      const parts = file.path.split("/");
      return parts.length > depth ? `${parts.slice(0, depth).join("/")}/…` : file.path;
    });
    const unique = [...new Set(shown)].slice(0, 200);
    const hidden = inScope.length - unique.length;
    return {
      id: call.id,
      name,
      ok: true,
      summary: `Listed ${inScope.length} file${inScope.length === 1 ? "" : "s"}${wanted ? ` under ${shortPath(wanted)}` : ""}`,
      content: [
        `${inScope.length} readable file${inScope.length === 1 ? "" : "s"}${wanted ? ` under ${wanted}` : ""}.`,
        ...unique,
        hidden > 0 ? `…and ${hidden} more (narrow the path or increase depth).` : "",
      ]
        .filter(Boolean)
        .join("\n"),
    };
  }

  if (name === "read_file") {
    const path = typeof args.path === "string" ? args.path.trim() : "";
    if (!isSafeRelativePath(path)) {
      return { id: call.id, name, ok: false, summary: "Refused an unsafe path", content: "That path is not a relative path inside the repository." };
    }
    const file = context.files.find((candidate) => candidate.path === path);
    if (!file) {
      const near = rankPaths(context.files, path, 5).map((candidate) => candidate.path);
      return {
        id: call.id,
        name,
        ok: false,
        summary: `Could not find ${shortPath(path)}`,
        content: [
          `There is no readable file at "${path}".`,
          near.length > 0 ? `Closest paths: ${near.join(", ")}` : "Use list_files to see what exists.",
        ].join("\n"),
      };
    }
    if (file.size > MAX_FILE_BYTES) {
      return {
        id: call.id,
        name,
        ok: false,
        summary: `Skipped ${shortPath(path)} (too large)`,
        content: `"${path}" is ${Math.round(file.size / 1024)} KB, which is too large to read in one call.`,
      };
    }

    const blob = await context.readFile(path);
    if (!blob) {
      return {
        id: call.id,
        name,
        ok: false,
        summary: `Could not read ${shortPath(path)}`,
        content: `"${path}" is binary or could not be decoded as text.`,
      };
    }
    return {
      id: call.id,
      name,
      ok: true,
      summary: `Read ${shortPath(path)}`,
      content: blob.truncated
        ? `Contents of ${path} (truncated at the size cap):\n\n${blob.text}\n\n…the rest of this file is not available.`
        : `Contents of ${path}:\n\n${blob.text}`,
    };
  }

  // search_code
  const query = typeof args.query === "string" ? args.query.trim() : "";
  if (!query) {
    return { id: call.id, name, ok: false, summary: "Empty search", content: "A search needs a query." };
  }
  if (query.length > 200) {
    return { id: call.id, name, ok: false, summary: "Search too long", content: "Keep the search under 200 characters." };
  }
  const hits = await context.search(query);
  return {
    id: call.id,
    name,
    ok: true,
    summary: hits.length > 0 ? `Searched "${query}" · ${hits.length} hit${hits.length === 1 ? "" : "s"}` : `Searched "${query}" · no hits`,
    content: formatHits(hits),
  };
}
